const fs=require("fs");
function strs(p){
  const buf=fs.readFileSync(p);let o="";
  for(let i=0;i<buf.length;i++){const c=buf[i];if(c>=32&&c<127)o+=String.fromCharCode(c);else o+="\n";}
  return o.split("\n").filter(s=>s.length>=3);
}
for(const f of ["Root_project_gradle.class","Root_project_gradle$1.class","Root_project_gradle$2.class","Application_gradle.class","CommonConventionsPlugin.class"]){
  const p="/tmp/logic-extract/io/swcode/urbo/build/logic/"+f;
  if(!fs.existsSync(p)){console.log("MISSING "+f);continue;}
  console.log("\n==== "+f+" ====");
  strs(p).filter(s=>/token|RepoAuth|github|gpr|maven|repo|s3|amazon|http|url|plugin|swcode|credential/i.test(s)).slice(0,30).forEach(s=>console.log("  "+s));
}
EOF
node /tmp/trace.js 2>&1

